insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f1ddfa70-e478-4378-a4de-8573d86f02f8', 'situacion', 'SITUACIÓN · Pregunta 3', 'ctx-sit', '<p>En un grupo de 40 estudiantes de un preuniversitario de Popayán se registró la jornada en la que estudian y su género. Los resultados se organizaron en la siguiente tabla:</p><table class="ctx-table"><tr><th></th><th>Mujeres</th><th>Hombres</th><th>Total</th></tr><tr><td>Sabatino</td><td>12</td><td>8</td><td>20</td></tr><tr><td>Intensivo</td><td>10</td><td>10</td><td>20</td></tr><tr><td><b>Total</b></td><td>22</td><td>18</td><td>40</td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('609ea15a-0dea-4431-b9e6-89f62029da8e', 'situacion', 'SITUACIÓN · Pregunta 4', 'ctx-sit', '<p>En un lote rectangular de 12 m de largo por 8 m de ancho se construirá un jardín rectangular central, rodeado por un sendero de 2 m de ancho por los cuatro costados, como muestra la figura:</p><div class="ctx-fig"><svg viewBox="0 0 340 210" role="img" aria-label="Figura: lote rectangular con jardín central y sendero perimetral">
<rect x="50" y="20" width="240" height="160" fill="#FAF3DC" stroke="#2A2418" stroke-width="2"/>
<rect x="90" y="60" width="160" height="80" fill="rgba(166,124,0,0.14)" stroke="#A67C00" stroke-width="2"/>
<text x="170" y="105" font-size="13" font-weight="700" fill="#8F6B00" text-anchor="middle">Jardín</text>
<text x="170" y="46" font-size="11" fill="#6B6248" text-anchor="middle">sendero · 2 m de ancho</text>
