  (select id from public.lotes where codigo = '2026-B'), true;
insert into public.cuestionario_preguntas (cuestionario_id, pregunta_id, orden) values ('b5a59c81-45b2-483d-b928-dfec3d4d0c0f', '8943d268-9089-4055-8d1d-23de0cfba50f', 1);
